        jobWidget.id = "kh-job-widget";
        jobWidget.classList.add("kh-col-lg-9", "kh-col-sm-12", "kh-pl-lg-3");

        var embedJobContainer = document.getElementById("kh-embed-job-container");
        embedJobContainer.appendChild(jobWidget)
